-- HIT - Archetype 흥미(RIASEC) 단일 유형 해설 6개 (2026-10-12, R4)
-- 기존 조합 해설 RIASEC-XYZ 26개는 120가지 순서 조합 중 일부만 있어 대부분 비어 있었다 → 상위 2개 흥미마다 단일 유형 해설을 붙인다
-- 선택: lib/hit/report-assembler.ts selectModules → RIASEC-TOP-{1·2위}, 정확히 맞는 조합 RIASEC-{Top3}가 있으면 함께
-- 재실행 가능. 롤백: DELETE FROM hit_report_modules WHERE id LIKE 'RIASEC-TOP-%';

ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, title = EXCLUDED.title, content = EXCLUDED.content, updated_at = now();
