INSERT INTO public.hit_report_modules (id, category, title, content) VALUES
('RIASEC-TOP-R', 'riasec', '현실형 — 손과 도구로 만드는 일', '직접 손으로 만들고, 도구와 장비를 다루며, 눈에 보이는 결과를 내는 일에 마음이 끌립니다. 말보다 행동으로 증명하는 환경에서 만족이 큽니다. 제작·엔지니어링·현장 운영·영상 촬영처럼 실물을 다루는 직무와 잘 맞습니다. 마케팅 안에서도 촬영·제작·공간 연출처럼 손이 가는 역할에서 강점을 살릴 수 있습니다.'),
('RIASEC-TOP-I', 'riasec', '탐구형 — 분석하고 원리를 파고드는 일', '왜 그런지 원리를 파고들고, 자료를 분석해 답을 찾는 일에 마음이 끌립니다. 혼자 깊이 생각할 시간이 있을 때 실력이 나옵니다. 데이터 분석·리서치·전략·연구 직무와 잘 맞습니다. 마케팅에서는 소비자 조사, 퍼포먼스 분석, 시장 분석처럼 근거를 만드는 역할에서 빛납니다.'),
('RIASEC-TOP-A', 'riasec', '예술형 — 표현하고 창작하는 일', '새로운 것을 상상하고, 나만의 방식으로 표현하는 일에 마음이 끌립니다. 정해진 틀보다 자유롭게 시도할 수 있는 환경에서 에너지가 납니다. 디자인·콘텐츠·카피·크리에이티브 직무와 잘 맞습니다. 아이디어를 결과물로 남기는 습관을 들이면 포트폴리오가 곧 경쟁력이 됩니다.'),
('RIASEC-TOP-S', 'riasec', '사회형 — 사람을 돕고 연결하는 일', '사람을 돕고, 가르치고, 서로를 연결하는 일에 마음이 끌립니다. 내가 한 일이 누군가에게 도움이 됐다는 것을 느낄 때 가장 보람을 느낍니다. 교육·HR·고객 경험·커뮤니티 운영 직무와 잘 맞습니다. 마케팅에서는 커뮤니티·CX·브랜드 경험처럼 사람과 직접 닿는 역할에서 강점이 큽니다.'),
('RIASEC-TOP-E', 'riasec', '진취형 — 이끌고 설득하는 일', '사람을 이끌고, 설득하고, 기회를 만들어 내는 일에 마음이 끌립니다. 목표가 분명하고 성과가 보이는 환경에서 힘을 냅니다. 기획·영업·사업개발·마케팅 전략·창업과 잘 맞습니다. 작은 프로젝트라도 직접 이끌어 본 경험이 이 흥미를 강점으로 바꿔 줍니다.'),
('RIASEC-TOP-C', 'riasec', '관습형 — 정리하고 체계를 세우는 일', '정보를 정리하고, 체계를 세우고, 꼼꼼하게 관리하는 일에 마음이 끌립니다. 기준이 분명하고 예측 가능한 환경에서 안정감을 느낍니다. 운영·재무·데이터 관리·품질 관리 직무와 잘 맞습니다. 마케팅에서는 예산·KPI 관리, 캠페인 운영, 성과 보고처럼 정확함이 필요한 역할에서 신뢰를 얻습니다.')
